description:
Each function below must produce text in an exact layout. Read the format specification in lesson 2.04 (and the `std::format` page it summarises) and write each one, most easily as a single `std::format` call.

| Function | Output |
|---|---|
| `priceLine(item, quantity, unitPrice)` | the item **left**-aligned in 12 characters, the quantity **right**-aligned in 4, then ` x `, then the price right-aligned in 8 with exactly 2 decimals |
| `hexWord(value)` | `0x` followed by exactly 8 **upper-case** hex digits, zero-padded |
| `signedDelta(delta)` | the number with a sign always shown, so zero is `+0` |
| `banner(title, width)` | the title **centred** in `width` characters, padded with `=`; when the padding is odd, the extra `=` goes on the right; a title longer than `width` is unchanged |
| `binaryByte(value)` | the low 8 bits of `value` as exactly 8 binary digits |
| `percent(fraction)` | `fraction` times 100 with exactly 1 decimal, then `%` |

```cpp-norun
std::string priceLine(std::string_view item, int quantity, double unitPrice);
std::string hexWord(std::uint32_t value);
std::string signedDelta(int delta);
std::string banner(std::string_view title, std::size_t width);
std::string binaryByte(unsigned value);
std::string percent(double fraction);
```

starter.solution.cpp:
#include <cstdint>
#include <string>
#include <string_view>

std::string priceLine(std::string_view item, int quantity, double unitPrice) { return ""; }
std::string hexWord(std::uint32_t value) { return ""; }
std::string signedDelta(int delta) { return ""; }
std::string banner(std::string_view title, std::size_t width) { return ""; }
std::string binaryByte(unsigned value) { return ""; }
std::string percent(double fraction) { return ""; }

solution.solution.cpp:
#include <cstdint>
#include <format>
#include <string>
#include <string_view>

std::string priceLine(std::string_view item, int quantity, double unitPrice)
{
    return std::format("{:<12}{:>4} x {:>8.2f}", item, quantity, unitPrice);
}

std::string hexWord(std::uint32_t value)
{
    return std::format("0x{:08X}", value);
}

std::string signedDelta(int delta)
{
    return std::format("{:+}", delta);
}

std::string banner(std::string_view title, std::size_t width)
{
    return std::format("{:=^{}}", title, width);
}

std::string binaryByte(unsigned value)
{
    return std::format("{:08b}", value & 0xFFu);
}

std::string percent(double fraction)
{
    return std::format("{:.1f}%", fraction * 100);
}

unitTests:
TEST("a price line") {
    CHECK_EQ(priceLine("Lantern", 3, 4.5), std::string("Lantern        3 x     4.50"));
    CHECK_EQ(priceLine("Rope", 12, 129.999), std::string("Rope          12 x   130.00"));
    CHECK_EQ(priceLine("A very long name", 1, 0), std::string("A very long name   1 x     0.00"));
}
TEST("hex words") {
    CHECK_EQ(hexWord(255), std::string("0x000000FF"));
    CHECK_EQ(hexWord(0xDEADBEEF), std::string("0xDEADBEEF"));
    CHECK_EQ(hexWord(0), std::string("0x00000000"));
}
TEST("signed deltas") {
    CHECK_EQ(signedDelta(5), std::string("+5"));
    CHECK_EQ(signedDelta(-12), std::string("-12"));
    CHECK_EQ(signedDelta(0), std::string("+0"));
}
TEST("banners") {
    CHECK_EQ(banner("abc", 8), std::string("==abc==="));
    CHECK_EQ(banner("ab", 6), std::string("==ab=="));
    CHECK_EQ(banner("title", 3), std::string("title"));
    CHECK_EQ(banner("", 4), std::string("===="));
}
TEST("binary bytes") {
    CHECK_EQ(binaryByte(5), std::string("00000101"));
    CHECK_EQ(binaryByte(255), std::string("11111111"));
    CHECK_EQ(binaryByte(0x1F0), std::string("11110000"));
}
TEST("percentages") {
    CHECK_EQ(percent(0.1234), std::string("12.3%"));
    CHECK_EQ(percent(1), std::string("100.0%"));
    CHECK_EQ(percent(0), std::string("0.0%"));
}

